def build_dataset() -> list:
    dataset = []
    bloques = [
        ("citas",         EJEMPLOS_CITAS),
        ("socratico",     EJEMPLOS_SOCRATICO),
        ("academico",     EJEMPLOS_ACADEMICO),
        ("incertidumbre", EJEMPLOS_INCERTIDUMBRE),
    ]
    for comportamiento, ejemplos in bloques:
        for ej in ejemplos:
            record = {
                "messages": [
                    {"role": "system",    "content": SYSTEM_PROMPT},
                    {"role": "user",      "content": ej["user"]},
                    {"role": "assistant", "content": ej["assistant"]}
                ],
                "_meta": {
                    "comportamiento": comportamiento,
                    "longitud_respuesta": len(ej["assistant"].split()),
                    "personaje": "rust_cohle_v2",
                    "version": 2
                }
            }
            dataset.append(record)

    random.seed(42)
    random.shuffle(dataset)
    return dataset


def save_jsonl(dataset: list, path: Path) -> None:
    with open(path, 'w', encoding='utf-8') as f:
        for record in dataset:
            f.write(json.dumps(record, ensure_ascii=False) + '\n')


def save_clean_jsonl(dataset: list, path: Path) -> Path:
    clean_path = path.parent / (path.stem + "_clean.jsonl")
    with open(clean_path, 'w', encoding='utf-8') as f:
        for record in dataset:
            clean = {"messages": record["messages"]}
            f.write(json.dumps(clean, ensure_ascii=False) + '\n')
    return clean_path


def print_stats(dataset: list) -> None:
    from collections import Counter
    comportamientos = Counter(r["_meta"]["comportamiento"] for r in dataset)
    longitudes = [r["_meta"]["longitud_respuesta"] for r in dataset]

    print("\n" + "=" * 60)
    print("  DATASET RUST COHLE v2 — ESTADÍSTICAS")
    print("=" * 60)
    print(f"  Total de ejemplos     : {len(dataset)}")
    print(f"\n  Por comportamiento:")
    for comp, count in sorted(comportamientos.items()):
        pct = 100 * count / len(dataset)
        print(f"    {comp:<20}: {count:3d} ejemplos ({pct:.0f}%)")
    print(f"\n  Longitud de respuestas (palabras):")
    print(f"    Mínima  : {min(longitudes)}")
    print(f"    Máxima  : {max(longitudes)}")
    print(f"    Promedio: {sum(longitudes)//len(longitudes)}")
    print("=" * 60)


